<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.405" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/ParseBinlog.cs << 'CSHARPEOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
foreach (var e in errors)
{
    var project = e.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {e.File}({e.LineNumber},{e.ColumnNumber}): error {e.Code}: {e.Text}");
}

Console.WriteLine("\n=== BUILD WARNINGS ===");
foreach (var w in warnings)
{
    var project = w.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {w.File}({w.LineNumber},{w.ColumnNumber}): warning {w.Code}: {w.Text}");
}

// Show project dependency info
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    var hasErrors = p.FindChildrenRecursive<Error>().Any();
    Console.WriteLine($"Project: {p.Name} | Succeeded: {p.Succeeded} | HasErrors: {hasErrors}");
}
