using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Extract source files from the binlog
Console.WriteLine("=== SOURCE FILES EMBEDDED ===");
var sourceFiles = build.SourceFiles;
if (sourceFiles != null)
{
    foreach (var kvp in sourceFiles)
    {
        Console.WriteLine($"\n--- FILE: {kvp.Key} ---");
        Console.WriteLine(kvp.Value);
    }
}

// Look for project references / package references
Console.WriteLine("\n=== SEARCHING FOR PACKAGE REFS ===");
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items)
{
    if (item.Name?.Contains("PackageReference") == true || item.Name?.Contains("ProjectReference") == true)
    {
        var project = item.GetNearestParent<Project>();
        Console.WriteLine($"[{project?.Name}] {item.Name}: {item.Text}");
    }
}
